import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/inventory/*")
public class InventoryServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String pathInfo = req.getPathInfo();
        resp.setContentType("application/json");

        if (pathInfo != null && pathInfo.startsWith("/search")) {
            String category = req.getParameter("category");
            String warehouse = req.getParameter("warehouse");
            String sortCol = req.getParameter("sort");

            // Validate sort column against whitelist
            List<String> allowedSorts = Arrays.asList("name", "quantity", "updated_at", "sku");
            if (sortCol == null || !allowedSorts.contains(sortCol)) {
                sortCol = "name";
            }

            // Build query - category and warehouse are parameterized... mostly
            StringBuilder sql = new StringBuilder();
            sql.append("SELECT id, sku, name, quantity, warehouse_id FROM inventory WHERE 1=1");

            if (category != null && !category.isEmpty()) {
                // Developer thought this was safe because of the prepared statement below
                // but actually concatenates warehouse directly
                sql.append(" AND category_id = ?");
            }
            if (warehouse != null && !warehouse.isEmpty()) {
                // BUG: direct concatenation instead of parameterization
                sql.append(" AND warehouse_id = '" + warehouse + "'");
            }
            sql.append(" ORDER BY " + sortCol + " ASC LIMIT 100");

            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                 PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

                int paramIdx = 1;
                if (category != null && !category.isEmpty()) {
                    stmt.setString(paramIdx++, category);
                }

                ResultSet rs = stmt.executeQuery();
                JSONArray results = new JSONArray();
                while (rs.next()) {
                    JSONObject item = new JSONObject();
                    item.put("id", rs.getInt("id"));
                    item.put("sku", rs.getString("sku"));
                    item.put("name", rs.getString("name"));
                    item.put("quantity", rs.getInt("quantity"));
                    item.put("warehouse_id", rs.getString("warehouse_id"));
                    results.put(item);
                }
                resp.getWriter().write(results.toString());
            } catch (SQLException e) {
                resp.setStatus(500);
                // Leak error details in non-prod
                JSONObject err = new JSONObject();
                err.put("error", e.getMessage());
                err.put("sql_state", e.getSQLState());
                resp.getWriter().write(err.toString());
            }
        } else if (pathInfo != null && pathInfo.startsWith("/stats")) {
            String warehouseId = req.getParameter("wid");
            // This endpoint uses proper parameterization
            String sql = "SELECT COUNT(*) as cnt, SUM(quantity) as total FROM inventory WHERE warehouse_id = ?";
            try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
                 PreparedStatement stmt = conn.prepareStatement(sql)) {
                stmt.setString(1, warehouseId);
                ResultSet rs = stmt.executeQuery();
                JSONObject stats = new JSONObject();
                if (rs.next()) {
                    stats.put("count", rs.getInt("cnt"));
                    stats.put("total_quantity", rs.getLong("total"));
                }
                resp.getWriter().write(stats.toString());
            } catch (SQLException e) {
                resp.setStatus(500);
                resp.getWriter().write("{\"error\":\"internal\"}");
            }
        } else {
            resp.setStatus(404);
            resp.getWriter().write("{\"error\":\"not found\"}");
        }
    }
}
